const jobSchemaResponseTransformer = (data: any) => {
    data.createdAt = new Date(data.createdAt);
    data.updatedAt = new Date(data.updatedAt);
    if (data.completedAt) {
        data.completedAt = new Date(data.completedAt);
    }
    if (data.payByTime) {
        data.payByTime = new Date(data.payByTime);
    }
    if (data.submitResultTime) {
        data.submitResultTime = new Date(data.submitResultTime);
    }
    if (data.unlockTime) {
        data.unlockTime = new Date(data.unlockTime);
    }
    if (data.externalDisputeUnlockTime) {
        data.externalDisputeUnlockTime = new Date(data.externalDisputeUnlockTime);
    }
    data.events = data.events.map((item: any) => {
        item.createdAt = new Date(item.createdAt);
        item.updatedAt = new Date(item.updatedAt);
        item.blobs = item.blobs.map((item: any) => fileSchemaResponseTransformer(item));
        item.links = item.links.map((item: any) => linkSchemaResponseTransformer(item));
        return item;
    });
    if (data.share) {
        data.share = jobShareSchemaResponseTransformer(data.share);
    }
    return data;
};

